// `#events/membership` is a virtual module generated by the module: it re-exports
// `hasActiveSubscription` from @frigear-nu/subscriptions when that is installed, and a fail-closed
// stub otherwise.
import { hasActiveSubscription } from '#events/membership'
import type { MembershipRequirement } from '../../types'

/** True when `requirement` is null, or the user holds a matching active subscription. */
export async function meetsMembership(userId: number, requirement: MembershipRequirement | undefined): Promise<boolean> {
  if (!requirement) return true
  return hasActiveSubscription(userId, requirement === 'any' ? {} : { plans: requirement })
}
